values
('bmlt-sterilization-disinfection-waste-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',4400,$json${"question":"Which process destroys all forms of microbial life, including bacterial spores?","translation":"","options":["Cleaning","Disinfection","Sterilization","Antisepsis"],"correctIndex":2,"explanation":"Sterilization eliminates all forms of microbial life, including spores.","explanationNe":"Sterilization ले spores सहित सबै प्रकारका सूक्ष्मजीव नष्ट गर्छ।","topic":"Sterilization principles"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',4401,$json${"question":"Which indicator provides the most direct evidence that a sterilization cycle has killed highly resistant microorganisms?","translation":"","options":["Chemical indicator tape","Biological indicator","Autoclave pressure gauge","Cycle printout only"],"correctIndex":1,"explanation":"Biological indicators use resistant spores to assess microbial inactivation.","explanationNe":"Biological indicator मा प्रतिरोधी spores प्रयोग गरी sterilization प्रभावकारिता जाँचिन्छ।","topic":"Sterilization monitoring"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',4402,$json${"question":"Which organism is commonly used as a biological indicator for steam sterilization?","translation":"","options":["Geobacillus stearothermophilus","Escherichia coli","Staphylococcus aureus","Candida albicans"],"correctIndex":0,"explanation":"Geobacillus stearothermophilus spores are used to monitor steam sterilization.","explanationNe":"Steam sterilization जाँच्न Geobacillus stearothermophilus spores प्रयोग गरिन्छ।","topic":"Biological indicators"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4403,$json${"question":"What is the usual purpose of a chemical indicator strip inside an autoclave pack?","translation":"","options":["Confirm exposure to selected process conditions","Prove sterility of every item","Identify bacterial species","Measure endotoxin level"],"correctIndex":0,"explanation":"Chemical indicators show exposure to one or more sterilization parameters but do not prove sterility.","explanationNe":"Chemical indicator ले केही प्रक्रिया parameter पुगेको देखाउँछ, तर sterility प्रमाणित गर्दैन।","topic":"Chemical indicators"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',4404,$json${"question":"Which combination is essential for effective steam sterilization?","translation":"","options":["Steam, adequate temperature, pressure and exposure time","Dry air and ultraviolet light only","Alcohol vapour alone","Low temperature and short exposure"],"correctIndex":0,"explanation":"Saturated steam transfers heat efficiently; validated time, temperature and pressure are required.","explanationNe":"Saturated steam ले प्रभावकारी heat transfer गर्छ; निर्धारित समय, तापक्रम र pressure आवश्यक हुन्छ।","topic":"Autoclaving"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',4405,$json${"question":"Why must air be removed from a steam sterilizer chamber?","translation":"","options":["Air prevents effective steam contact and heat transfer","Air increases spore resistance","Air sterilizes the load","Air prevents condensation"],"correctIndex":0,"explanation":"Trapped air creates cold spots and reduces steam penetration.","explanationNe":"भित्र थुनिएको हावाले cold spot बनाउँछ र steam प्रवेश घटाउँछ।","topic":"Autoclaving"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',4406,$json${"question":"Which material is generally unsuitable for routine steam autoclaving unless specifically validated?","translation":"","options":["Heat-sensitive plastic","Stainless steel surgical instrument","Autoclavable glassware","Steam-compatible dressing pack"],"correctIndex":0,"explanation":"Heat-sensitive materials may deform or be damaged; manufacturer compatibility must be checked.","explanationNe":"ताप सहन नसक्ने plastic बिग्रन सक्छ; निर्माता निर्देशिका जाँच्नुपर्छ।","topic":"Sterilization selection"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',4407,$json${"question":"Which method is suitable for sterilizing heat- and moisture-sensitive medical devices when compatible?","translation":"","options":["Ethylene oxide gas","Boiling water","Pasteurization","Open-flame heating"],"correctIndex":0,"explanation":"Ethylene oxide can sterilize compatible heat- and moisture-sensitive devices, but requires controlled aeration and safety measures.","explanationNe":"Ethylene oxide ले मिल्ने heat/moisture-sensitive उपकरण sterilize गर्न सक्छ; aeration र safety चाहिन्छ।","topic":"Low-temperature sterilization"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',4408,$json${"question":"What is the primary limitation of 70% alcohol as a disinfectant?","translation":"","options":["It is not reliably sporicidal","It cannot kill enveloped viruses","It cannot act on vegetative bacteria","It is always ineffective on skin"],"correctIndex":0,"explanation":"Alcohol is effective against many vegetative bacteria and enveloped viruses but does not reliably destroy bacterial spores.","explanationNe":"Alcohol धेरै vegetative bacteria र enveloped virus विरुद्ध प्रभावकारी हुन्छ, तर spores विश्वसनीय रूपमा नष्ट गर्दैन।","topic":"Disinfectants"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',4409,$json${"question":"Which factor can reduce the effectiveness of a disinfectant on a contaminated surface?","translation":"","options":["Presence of organic matter","Correct contact time","Correct dilution","Pre-cleaning"],"correctIndex":0,"explanation":"Blood, serum and other organic material can interfere with disinfectant activity; cleaning first is important.","explanationNe":"रगत तथा organic पदार्थले disinfectant को असर घटाउन सक्छ; पहिले सफाइ गर्नुपर्छ।","topic":"Disinfection practice"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',4410,$json${"question":"What does the term contact time mean in disinfection?","translation":"","options":["Time the surface remains wet with disinfectant as directed","Time required to prepare the solution","Time between sample collection and testing","Time needed to dry the floor"],"correctIndex":0,"explanation":"The surface must remain wet for the product's specified contact time.","explanationNe":"निर्माताले तोकेको समयसम्म सतह disinfectant ले भिजेको रहनुपर्छ।","topic":"Disinfection practice"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',4411,$json${"question":"Which chlorine-based product is commonly used for environmental surface disinfection when prepared at the correct concentration?","translation":"","options":["Sodium hypochlorite","Ethylene oxide","Glutaraldehyde","Chlorhexidine mouthwash"],"correctIndex":0,"explanation":"Sodium hypochlorite is widely used for environmental disinfection; concentration and contact time depend on the task and local guidance.","explanationNe":"Sodium hypochlorite वातावरणीय सतह disinfect गर्न प्रयोग हुन्छ; concentration र contact time कामअनुसार हुन्छ।","topic":"Chemical disinfection"}$json$::jsonb,true),
('bmlt-sterilization-disinfection-waste-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',4412,$json${"question":"Why should bleach solutions be prepared and stored according to facility guidance?","translation":"","options":["Available chlorine can decrease over time and with light or heat","Bleach becomes a biological indicator","Bleach spontaneously becomes sterile water","Bleach cannot react with organic matter"],"correctIndex":0,"explanation":"Hypochlorite solutions lose activity during storage, especially with heat, light and time.","explanationNe":"Hypochlorite को प्रभाव समय, ताप र प्रकाशले घट्न सक्छ।","topic":"Disinfectant preparation"}$json$::jsonb,true),
