('bmlt-sterilization-disinfection-waste-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',4414,$json${"question":"What is the correct first step before disinfecting a visibly blood-contaminated reusable instrument?","translation":"","options":["Clean to remove visible soil using appropriate precautions","Place directly in a storage cabinet","Wipe once with dry tissue only","Package without cleaning"],"correctIndex":0,"explanation":"Cleaning removes soil and organic material so subsequent disinfection or sterilization can work effectively.","explanationNe":"पहिले सफाइ गर्दा फोहोर र organic पदार्थ हट्छ र त्यसपछि disinfection/sterilization प्रभावकारी हुन्छ।","topic":"Cleaning"}$json$::jsonb,true),
